"""The marker grammar of the facts the docs repeat (tool/docs/sync_facts.py).

A generated fact sits between two markers that name it and its source. In Markdown, inside a
sentence, a list item or a table cell (an inline span):

    … with <!-- docs:KEY from SOURCE; generated by make docs, do not edit -->BODY<!-- /docs:KEY --> …

In Markdown, as a paragraph, list or table of its own (a block), each marker alone on its line
and the body between blank lines. In YAML, comment lines at the indentation of the keys between
them:

    # docs:KEY from SOURCE; generated by make docs, do not edit
    BODY
    # /docs:KEY

The open marker is read leniently (`<!-- docs:KEY -->` is enough) and written in full. Examples
in prose use the placeholder `KEY` or `…`, which the grammar does not match. This module only
finds, checks and replaces spans; which keys exist, and where, is tool/docs/fact_registry.py's.

Every problem is reported as `RULE path:line: message`, all of them before the tool exits:

    M1   an open marker without a close
    M2   a close marker without an open
    M3   a close marker naming another key
    M4   markers nested inside a span
    M5   a key that is not in the registry
    M6   a fact whose kind does not suit the file (a YAML fact in Markdown, or the reverse)
    M7   a marker in a file that is not one of the fact's targets
    M8   a target that holds no marker for the fact
    M9   an inline open marker that begins its line (CommonMark would read the line as raw HTML,
         and the code spans in it would show their backticks)
    M10  an inline body with a blank line
    M11  an inline body in a table row that spans lines
    M12  a wrapped inline body whose continuation line starts a block (#, >, a list marker, <)
    M13  a block marker that is not alone on its line
    M14  a marker inside a fenced code block, where readers would see it
    M15  a YAML close marker at another indentation from its open marker
    M16  a marker in CHANGELOG.md (release-please's), llms.txt (read as plain text by AI tools)
         or .planning/ (the planning files')
"""

from __future__ import annotations

import re
from collections.abc import Iterable, Mapping
from dataclasses import dataclass

KEY = r"[a-z][a-z0-9]*(?:-[a-z0-9]+)*"
MD_OPEN = re.compile(rf"<!--[ \t]*docs:(?P<key>{KEY})(?P<label>(?:[ \t](?:(?!-->).)*)?)-->")
MD_CLOSE = re.compile(rf"<!--[ \t]*/docs:(?P<key>{KEY})[ \t]*-->")
YAML_OPEN = re.compile(rf"^(?P<indent> *)# docs:(?P<key>{KEY})(?: .*)?$", re.M)
YAML_CLOSE = re.compile(rf"^(?P<indent> *)# /docs:(?P<key>{KEY}) *$", re.M)

KINDS = ("inline", "block", "yaml")
# Files whose owner is not this tool (M16).
FORBIDDEN = {
    "CHANGELOG.md": "release-please owns it",
    "llms.txt": "AI tools read it as plain text",
}
FORBIDDEN_PREFIX = (".planning/", "the planning files own it")

# What CommonMark reads as the start of a block when it begins a line (M12), and the container
# prefixes (block quote, list item) a line may start with before its content (M9).
_BLOCK_START = re.compile(
    r"(?:#{1,6}(?:[ \t]|$)|>|[-+*](?:[ \t]|$)|\d{1,9}[.)](?:[ \t]|$)|<|=+\s*$|-+\s*$)"
)
_CONTAINER = re.compile(r"(?:>|[-+*](?=[ \t]|$)|\d{1,9}[.)](?=[ \t]|$))[ \t]*")
_FENCE = re.compile(r"^[ \t]*(?P<fence>`{3,}|~{3,})(?P<info>.*)$")


@dataclass(frozen=True)
class MarkerError:
    """A broken marker: `rule` is M1 to M16 (docs/agents/conventions.md, Generated files)."""

    rule: str
    path: str
    line: int
    message: str

    def __str__(self) -> str:
        return f"{self.rule} {self.path}:{self.line}: {self.message}"


@dataclass(frozen=True)
class Span:
    """One generated fact in a file: offsets of its whole text, from open marker to close."""

    key: str
    kind: str
    path: str
    line: int
    start: int
    end: int
    body: str
    indent: str


@dataclass(frozen=True)
class Rendered:
    """A fact's current value, and the source label its open marker names."""

    source: str
    body: str


def syntax_of(path: str) -> str:
    """ "yaml" for YAML files, "markdown" for the rest (Markdown and plain text)."""
    return "yaml" if path.endswith((".yml", ".yaml")) else "markdown"


def open_marker(key: str, source: str) -> str:
    return f"<!-- docs:{key} from {source}; generated by make docs, do not edit -->"


def close_marker(key: str) -> str:
    return f"<!-- /docs:{key} -->"


def yaml_open_marker(key: str, source: str) -> str:
    return f"# docs:{key} from {source}; generated by make docs, do not edit"


def yaml_close_marker(key: str) -> str:
    return f"# /docs:{key}"


def normalise(text: str) -> str:
    """Whitespace folded, so a body a person or Prettier re-wrapped is not drift."""
    return " ".join(text.split())


def line_of(text: str, offset: int) -> int:
    return text.count("\n", 0, offset) + 1


def fenced_lines(text: str) -> set[int]:
    """1-based numbers of the lines inside fenced code blocks, fences included.

    A fence closes only with the character that opened it, at least as long, and nothing but
    spaces after it, as in CommonMark; a fence left open runs to the end of the file. Any
    indentation is accepted, since fences inside list items are indented.
    """
    inside: set[int] = set()
    opened: str | None = None
    for number, line in enumerate(text.split("\n"), start=1):
        match = _FENCE.match(line)
        if opened is None:
            if match and not (match["fence"][0] == "`" and "`" in match["info"]):
                opened = match["fence"]
                inside.add(number)
            continue
        inside.add(number)
        if (
            match
            and match["fence"][0] == opened[0]
            and len(match["fence"]) >= len(opened)
            and not match["info"].strip()
        ):
            opened = None
    return inside


def forbidden_reason(path: str) -> str | None:
    if path in FORBIDDEN:
        return FORBIDDEN[path]
    if path.startswith(FORBIDDEN_PREFIX[0]):
        return FORBIDDEN_PREFIX[1]
    return None


@dataclass
class _Marker:
    key: str
    is_open: bool
    start: int
    end: int
    line: int


def scan(path: str, text: str, kinds: Mapping[str, str]) -> tuple[list[Span], list[MarkerError]]:
    """Every well-formed span in `text`, and every broken marker (M1 to M6, M9 to M16).

    `kinds` maps each key in the registry to its kind. All problems in the file are collected;
    a span is returned only when nothing about it is wrong.
    """
    scanner = _scan_yaml if syntax_of(path) == "yaml" else _scan_markdown
    spans, errors = scanner(path, text, kinds)
    return spans, sorted(errors, key=lambda e: (e.line, e.rule, e.message))


def _forbidden_errors(path: str, markers: Iterable[_Marker]) -> list[MarkerError]:
    reason = forbidden_reason(path)
    if reason is None:
        return []
    return [
        MarkerError("M16", path, m.line, f"no generated facts in this file ({reason})")
        for m in markers
    ]


def _pair(
    path: str, markers: list[_Marker]
) -> tuple[list[tuple[_Marker, _Marker]], list[MarkerError]]:
    """Pairs open and close markers (M1 to M4); nested spans and their outer span are dropped."""
    pairs: list[tuple[_Marker, _Marker]] = []
    errors: list[MarkerError] = []
    stack: list[tuple[_Marker, bool]] = []  # (open marker, poisoned by a marker inside it)
    for marker in markers:
        if marker.is_open:
            if stack:
                outer = stack[0][0]
                errors.append(
                    MarkerError(
                        "M4",
                        path,
                        marker.line,
                        f"docs:{marker.key} opens inside docs:{outer.key} (opened on line"
                        f" {outer.line}); spans cannot nest",
                    )
                )
                stack = [(entry, True) for entry, _ in stack]
            stack.append((marker, False))
            continue
        if not stack:
            errors.append(
                MarkerError("M2", path, marker.line, f"/docs:{marker.key} closes no open marker")
            )
            continue
        opener, poisoned = stack.pop()
        if opener.key != marker.key:
            errors.append(
                MarkerError(
                    "M3",
                    path,
                    marker.line,
                    f"/docs:{marker.key} closes docs:{opener.key} (opened on line {opener.line})",
                )
            )
            continue
        if not poisoned and not stack:
            pairs.append((opener, marker))
    for opener, _ in stack:
        errors.append(
            MarkerError(
                "M1", path, opener.line, f"docs:{opener.key} has no close marker /docs:{opener.key}"
            )
        )
    return pairs, errors


def _kind_errors(
    path: str, marker: _Marker, kinds: Mapping[str, str], syntax: str
) -> list[MarkerError]:
    kind = kinds.get(marker.key)
    if kind is None:
        return [
            MarkerError(
                "M5",
                path,
                marker.line,
                f"docs:{marker.key} is not a fact in tool/docs/fact_registry.py",
            )
        ]
    if (kind == "yaml") != (syntax == "yaml"):
        where = "YAML" if syntax == "yaml" else "Markdown"
        return [
            MarkerError(
                "M6",
                path,
                marker.line,
                f"docs:{marker.key} is a {kind} fact; it cannot stand in {where}",
            )
        ]
    return []


def _scan_markdown(
    path: str, text: str, kinds: Mapping[str, str]
) -> tuple[list[Span], list[MarkerError]]:
    found = [
        _Marker(m["key"], True, m.start(), m.end(), line_of(text, m.start()))
        for m in MD_OPEN.finditer(text)
    ] + [
        _Marker(m["key"], False, m.start(), m.end(), line_of(text, m.start()))
        for m in MD_CLOSE.finditer(text)
    ]
    found.sort(key=lambda m: m.start)
    if not found:
        return [], []
    forbidden = _forbidden_errors(path, found)
    if forbidden:
        return [], forbidden

    errors: list[MarkerError] = []
    fenced = fenced_lines(text)
    markers = []
    for marker in found:
        if marker.line in fenced:
            errors.append(
                MarkerError(
                    "M14",
                    path,
                    marker.line,
                    f"docs:{marker.key} is inside a fenced code block, where readers would see it",
                )
            )
        else:
            markers.append(marker)

    pairs, pair_errors = _pair(path, markers)
    errors += pair_errors
    paired = {id(m) for pair in pairs for m in pair}
    for marker in markers:
        if marker.is_open and id(marker) not in paired:
            errors += _kind_errors(path, marker, kinds, "markdown")

    spans = []
    for opener, closer in pairs:
        problems = _kind_errors(path, opener, kinds, "markdown")
        if not problems:
            kind = kinds[opener.key]
            problems = (
                _block_errors(path, text, opener, closer)
                if kind == "block"
                else _inline_errors(path, text, opener, closer)
            )
            if not problems:
                spans.append(_markdown_span(path, text, kind, opener, closer))
        errors += problems
    return spans, errors


def _line_bounds(text: str, offset: int) -> tuple[int, int]:
    start = text.rfind("\n", 0, offset) + 1
    end = text.find("\n", offset)
    return start, len(text) if end < 0 else end


def _only_containers(prefix: str) -> bool:
    """True when `prefix` holds only indentation and block-quote or list-item markers."""
    rest = prefix.lstrip()
    while rest:
        match = _CONTAINER.match(rest)
        if not match:
            return False
        rest = rest[match.end() :].lstrip()
    return True


def _inline_errors(path: str, text: str, opener: _Marker, closer: _Marker) -> list[MarkerError]:
    errors = []
    line_start, _ = _line_bounds(text, opener.start)
    if _only_containers(text[line_start : opener.start]):
        errors.append(
            MarkerError(
                "M9",
                path,
                opener.line,
                f"docs:{opener.key} begins its line, so CommonMark would read the line as raw HTML"
                " and show the backticks of its code spans; put text before it",
            )
        )
    body = text[opener.end : closer.start]
    if re.search(r"\n[ \t]*\n", body):
        errors.append(
            MarkerError(
                "M10",
                path,
                opener.line,
                f"docs:{opener.key} is inline but its body has a blank line",
            )
        )
    whole = text[opener.start : closer.end]
    if "\n" in whole and text[line_start:].lstrip().startswith("|"):
        errors.append(
            MarkerError(
                "M11",
                path,
                opener.line,
                f"docs:{opener.key} is in a table row but spans lines; a row is one line",
            )
        )
    offset = opener.start
    while True:
        newline = text.find("\n", offset, closer.start)
        if newline < 0:
            break
        offset = newline + 1
        _, line_end = _line_bounds(text, offset)
        content = text[offset:line_end].lstrip()
        if _BLOCK_START.match(content):
            errors.append(
                MarkerError(
                    "M12",
                    path,
                    line_of(text, offset),
                    f"a wrapped line of docs:{opener.key} starts with {content[:1]!r}, which would"
                    " start a new block; re-wrap it so that a word starts the line",
                )
            )
    return errors


def _block_errors(path: str, text: str, opener: _Marker, closer: _Marker) -> list[MarkerError]:
    errors = []
    for marker in (opener, closer):
        start, end = _line_bounds(text, marker.start)
        if text[start:end].strip() != text[marker.start : marker.end]:
            errors.append(
                MarkerError(
                    "M13",
                    path,
                    marker.line,
                    f"the block marker of docs:{marker.key} must stand alone on its line",
                )
            )
    return errors


def _markdown_span(path: str, text: str, kind: str, opener: _Marker, closer: _Marker) -> Span:
    line_start, _ = _line_bounds(text, opener.start)
    indent = text[line_start : opener.start] if kind == "block" else ""
    body = text[opener.end : closer.start]
    if kind == "block":
        body = "\n".join(
            line[len(indent) :] if line.startswith(indent) else line.lstrip()
            for line in body.rstrip(" \t").strip("\n").split("\n")
        )
    return Span(opener.key, kind, path, opener.line, opener.start, closer.end, body, indent)


def _scan_yaml(
    path: str, text: str, kinds: Mapping[str, str]
) -> tuple[list[Span], list[MarkerError]]:
    errors: list[MarkerError] = []
    # A Markdown-style marker in YAML is never right: report it once, unpaired.
    for regex in (MD_OPEN, MD_CLOSE):
        for match in regex.finditer(text):
            line = line_of(text, match.start())
            if match["key"] in kinds:
                errors.append(
                    MarkerError(
                        "M6",
                        path,
                        line,
                        f"docs:{match['key']} is written as a Markdown marker in a YAML file;"
                        " YAML facts use comment lines (# docs:KEY … and # /docs:KEY)",
                    )
                )
            else:
                errors.append(
                    MarkerError(
                        "M5",
                        path,
                        line,
                        f"docs:{match['key']} is not a fact in tool/docs/fact_registry.py",
                    )
                )
    found = [
        _Marker(m["key"], True, m.start(), m.end(), line_of(text, m.start()))
        for m in YAML_OPEN.finditer(text)
    ] + [
        _Marker(m["key"], False, m.start(), m.end(), line_of(text, m.start()))
        for m in YAML_CLOSE.finditer(text)
    ]
    found.sort(key=lambda m: m.start)
    forbidden = _forbidden_errors(path, found)
    if forbidden:
        return [], errors + forbidden
    pairs, pair_errors = _pair(path, found)
    errors += pair_errors
    paired = {id(m) for pair in pairs for m in pair}
    for marker in found:
        if marker.is_open and id(marker) not in paired:
            errors += _kind_errors(path, marker, kinds, "yaml")
    spans = []
    for opener, closer in pairs:
        problems = _kind_errors(path, opener, kinds, "yaml")
        open_indent = _yaml_indent(YAML_OPEN, text, opener.start)
        close_indent = _yaml_indent(YAML_CLOSE, text, closer.start)
        if open_indent != close_indent:
            problems.append(
                MarkerError(
                    "M15",
                    path,
                    closer.line,
                    f"/docs:{closer.key} is indented {len(close_indent)} spaces but its open marker"
                    f" {len(open_indent)}",
                )
            )
        if not problems:
            body_start = min(opener.end + 1, closer.start)
            lines = text[body_start : closer.start].split("\n")[:-1]
            body = "\n".join(
                line[len(open_indent) :] if line.startswith(open_indent) else line.lstrip()
                for line in lines
            )
            spans.append(
                Span(
                    opener.key,
                    "yaml",
                    path,
                    opener.line,
                    opener.start,
                    closer.end,
                    body,
                    open_indent,
                )
            )
        errors += problems
    return spans, errors


def _yaml_indent(regex: re.Pattern[str], text: str, start: int) -> str:
    match = regex.match(text, start)
    if match is None:  # start came from this regex, so it matches there
        raise ValueError(f"no marker at offset {start}")
    return match["indent"]


def check_placement(
    found: Mapping[str, Iterable[tuple[str, int]]], targets: Mapping[str, Iterable[str]]
) -> list[MarkerError]:
    """M7 and M8: every marker is in one of its fact's targets, and every target holds one.

    `found` maps each scanned path to the (key, line) of every open marker in it, well-formed
    or not (markers_in); `targets` maps each known key to the files that must hold it. Files no
    marker may be in at all (M16) are left to scan().
    """
    errors = []
    wanted = {key: set(paths) for key, paths in targets.items()}
    for path in sorted(found):
        if forbidden_reason(path):
            continue
        first: dict[str, int] = {}
        for key, line in found[path]:
            first.setdefault(key, line)
        for key in sorted(first):
            if key in wanted and path not in wanted[key]:
                errors.append(
                    MarkerError(
                        "M7",
                        path,
                        first[key],
                        f"docs:{key} is not expected here; add {path} to the fact's targets in"
                        " tool/docs/fact_registry.py, or remove the markers",
                    )
                )
    for key in sorted(wanted):
        for path in sorted(wanted[key]):
            if key not in {k for k, _ in found.get(path, ())}:
                errors.append(
                    MarkerError(
                        "M8",
                        path,
                        1,
                        f"has no docs:{key} span; restore it from git, or remove the file from the"
                        " fact's targets in tool/docs/fact_registry.py",
                    )
                )
    return errors


def markers_in(text: str, path: str) -> list[tuple[str, int]]:
    """(key, line) of every open marker in `text`, in either syntax, well-formed or not."""
    regexes = (MD_OPEN, YAML_OPEN) if syntax_of(path) == "yaml" else (MD_OPEN,)
    return sorted(
        (m["key"], line_of(text, m.start())) for regex in regexes for m in regex.finditer(text)
    )


def replacement(span: Span, rendered: Rendered) -> str:
    """The text that `span` becomes once its fact is current."""
    if span.kind == "inline":
        body = span.body if normalise(span.body) == normalise(rendered.body) else rendered.body
        return open_marker(span.key, rendered.source) + body + close_marker(span.key)
    if span.kind == "block":
        body = "\n".join(span.indent + line if line else line for line in rendered.body.split("\n"))
        return (
            open_marker(span.key, rendered.source)
            + "\n\n"
            + body
            + "\n\n"
            + span.indent
            + close_marker(span.key)
        )
    lines = "".join(
        f"{span.indent}{line}\n" if line else "\n" for line in rendered.body.split("\n")
    )
    return (
        span.indent
        + yaml_open_marker(span.key, rendered.source)
        + "\n"
        + lines
        + span.indent
        + yaml_close_marker(span.key)
    )


def rewrite(
    text: str, spans: Iterable[Span], rendered: Mapping[str, Rendered]
) -> tuple[str, list[str]]:
    """`text` with every span whose key is in `rendered` made current, and the keys that changed.

    Spans whose key is missing from `rendered` (its source could not be read) are left alone.
    """
    changed: list[str] = []
    for span in sorted(spans, key=lambda s: s.start, reverse=True):
        if span.key not in rendered:
            continue
        new = replacement(span, rendered[span.key])
        if text[span.start : span.end] != new:
            text = text[: span.start] + new + text[span.end :]
            changed.append(span.key)
    changed.reverse()
    return text, changed
